class TodoList:
    def __init__(self):
        self.tasks = {}
        self.user_tasks = {}
        self.counter = 0

    def addTask(self, userId: int, taskDescription: str, dueDate: int, tags: list[str]) -> int:
        self.counter += 1
        self.tasks[self.counter] = {'d': taskDescription, 'due': dueDate, 'tags': set(tags), 'done': False}
        self.user_tasks.setdefault(userId, []).append(self.counter)
        return self.counter

    def getAllTasks(self, userId: int) -> list[str]:
        ts = [self.tasks[t] for t in self.user_tasks.get(userId, []) if not self.tasks[t]['done']]
        ts.sort(key=lambda x: x['due'])
        return [t['d'] for t in ts]

    def getTasksForTag(self, userId: int, tag: str) -> list[str]:
        ts = [self.tasks[t] for t in self.user_tasks.get(userId, [])
              if not self.tasks[t]['done'] and tag in self.tasks[t]['tags']]
        ts.sort(key=lambda x: x['due'])
        return [t['d'] for t in ts]

    def completeTask(self, userId: int, taskId: int) -> None:
        t = self.tasks.get(taskId)
        if t and taskId in self.user_tasks.get(userId, []) and not t['done']:
            t['done'] = True

