class TodoList {
    struct Task { string desc; int due; unordered_set<string> tags; bool done; };
    unordered_map<int, Task> tasks;
    unordered_map<int, vector<int>> userTasks;
    int counter = 0;
public:
    TodoList() {}
    int addTask(int userId, string taskDescription, int dueDate, vector<string> tags) {
        tasks[++counter] = {taskDescription, dueDate, {tags.begin(), tags.end()}, false};
        userTasks[userId].push_back(counter);
        return counter;
    }
    vector<string> getTasks(int userId, bool filterTag, const string& tag = "") {
        vector<pair<int,string>> v;
        for (int id : userTasks[userId]) {
            auto& t = tasks[id];
            if (!t.done && (!filterTag || t.tags.count(tag))) v.push_back({t.due, t.desc});
        }
        sort(v.begin(), v.end());
        vector<string> res;
        for (auto& p : v) res.push_back(p.second);
        return res;
    }
    vector<string> getAllTasks(int userId) { return getTasks(userId, false); }
    vector<string> getTasksForTag(int userId, string tag) { return getTasks(userId, true, tag); }
    void completeTask(int userId, int taskId) {
        auto it = tasks.find(taskId);
        if (it != tasks.end() && !it->second.done && it->second.due >= 0) {
            auto& v = userTasks[userId];
            if (find(v.begin(), v.end(), taskId) != v.end()) it->second.done = true;
        }
    }
};

