import java.util.*;
class TodoList {
    private static class Task {
        String desc; int due; Set<String> tags; boolean done;
        Task(String d, int due, List<String> t) { desc = d; this.due = due; tags = new HashSet<>(t); done = false; }
    }
    private final Map<Integer, Task> tasks = new HashMap<>();
    private final Map<Integer, List<Integer>> userTasks = new HashMap<>();
    private int counter = 0;
    public TodoList() {}
    public int addTask(int userId, String taskDescription, int dueDate, List<String> tags) {
        tasks.put(++counter, new Task(taskDescription, dueDate, tags));
        userTasks.computeIfAbsent(userId, k -> new ArrayList<>()).add(counter);
        return counter;
    }
    private List<String> getTasks(int userId, String tag) {
        List<Task> v = new ArrayList<>();
        for (int id : userTasks.getOrDefault(userId, Collections.emptyList())) {
            Task t = tasks.get(id);
            if (!t.done && (tag == null || t.tags.contains(tag))) v.add(t);
        }
        v.sort((a, b) -> a.due - b.due);
        List<String> res = new ArrayList<>();
        for (Task t : v) res.add(t.desc);
        return res;
    }
    public List<String> getAllTasks(int userId) { return getTasks(userId, null); }
    public List<String> getTasksForTag(int userId, String tag) { return getTasks(userId, tag); }
    public void completeTask(int userId, int taskId) {
        Task t = tasks.get(taskId);
        if (t != null && !t.done && userTasks.getOrDefault(userId, Collections.emptyList()).contains(taskId))
            t.done = true;
    }
}

