var TodoList = function() {
    this.tasks = {};
    this.userTasks = {};
    this.counter = 0;
};
TodoList.prototype.addTask = function(userId, taskDescription, dueDate, tags) {
    this.tasks[++this.counter] = { desc: taskDescription, due: dueDate, tags: new Set(tags), done: false };
    (this.userTasks[userId] ||= []).push(this.counter);
    return this.counter;
};
TodoList.prototype.getTasks = function(userId, tag) {
    const v = (this.userTasks[userId] || [])
        .map(id => this.tasks[id])
        .filter(t => !t.done && (tag === null || t.tags.has(tag)));
    v.sort((a, b) => a.due - b.due);
    return v.map(t => t.desc);
};
TodoList.prototype.getAllTasks = function(userId) { return this.getTasks(userId, null); };
TodoList.prototype.getTasksForTag = function(userId, tag) { return this.getTasks(userId, tag); };
TodoList.prototype.completeTask = function(userId, taskId) {
    const t = this.tasks[taskId];
    if (t && !t.done && (this.userTasks[userId] || []).includes(taskId)) t.done = true;
};
